using UnityEngine;using UnityEditor;using Caronte;
public static class BuildMissionVisuals{
 static Material m,g,b,glass,pcb;static Transform Node(string n,Transform p){var go=new GameObject(n);go.transform.SetParent(p,false);return go.transform;}
 static GameObject Piece(Transform p,string n,PrimitiveType shape,Vector3 pos,Vector3 scale,Material mat){var go=GameObject.CreatePrimitive(shape);go.name=n;go.transform.SetParent(p,false);go.transform.localPosition=pos;go.transform.localScale=scale;go.GetComponent<Renderer>().sharedMaterial=mat;return go;}
 public static string Build(){var app=Object.FindFirstObjectByType<CarontePrototype>();var cv=app.GetComponent<CatalogVisuals>();if(!cv)cv=app.gameObject.AddComponent<CatalogVisuals>();cv.app=app;m=app.metal;g=app.gold;b=app.blue;glass=app.glass;pcb=app.green;
 System.IO.Directory.CreateDirectory("Assets/AssetHendrix/Prefabs/Catalog");
 for(int cat=0;cat<11;cat++)for(int option=0;option<3;option++){
 var root=new GameObject("Model_"+cat+"_"+option);var t=root.transform;
 if(cat==0){for(int x=-1;x<=1;x+=2)for(int z=-1;z<=1;z+=2)Piece(t,"StructuralRail",PrimitiveType.Cube,new Vector3(x*.9f,0,z*.5f),new Vector3(.09f,3,.09f),m);Piece(t,"StructuralPanel",PrimitiveType.Cube,new Vector3(0,0,.48f),new Vector3(1.8f,2.9f,.08f),g);Piece(t,"TopDeck",PrimitiveType.Cube,new Vector3(0,1.45f,0),new Vector3(1.8f,.08f,1),m);Piece(t,"BottomDeck",PrimitiveType.Cube,new Vector3(0,-1.45f,0),new Vector3(1.8f,.08f,1),m);if(option>0)for(int i=0;i<option;i++)Piece(t,"Reinforcement",PrimitiveType.Cube,new Vector3(0,-.5f+i,.45f),new Vector3(1.9f,.1f,.13f),m);}
 if(cat==1){if(option<2){Piece(t,"OpticalHousing",PrimitiveType.Cube,Vector3.zero,new Vector3(option==0?.6f:1.2f,.65f,.35f),g);for(int i=0;i<(option==0?2:4);i++){var part=Piece(t,i==0?"OpticalTube":"OpticalRing",PrimitiveType.Cylinder,new Vector3(0,0,-.25f-i*.15f),new Vector3(option==0?.42f:.9f,.12f,option==0?.42f:.9f),i==(option==0?1:3)?glass:m);part.transform.localRotation=Quaternion.Euler(90,0,0);}}else{Piece(t,"SensorHousing",PrimitiveType.Cube,Vector3.zero,new Vector3(.4f,.3f,.3f),pcb);Piece(t,"MagnetometerBoom",PrimitiveType.Cylinder,new Vector3(.5f,.1f,0),new Vector3(.035f,.5f,.035f),m).transform.localRotation=Quaternion.Euler(0,0,90);Piece(t,"ParticleDetector",PrimitiveType.Cube,new Vector3(.9f,.1f,0),new Vector3(.18f,.2f,.2f),glass);}}
 if(cat==2){if(option<2){for(int side=-1;side<=1;side+=2){var wing=Node("SolarWing",t);wing.localPosition=new Vector3(side*(option==0?.91f:1.8f),0,0);Piece(wing,"PanelFrame",PrimitiveType.Cube,Vector3.zero,new Vector3(option==0?.08f:1.5f,2.2f,option==0?.85f:.07f),m);for(int row=0;row<5;row++)Piece(wing,"CellStrip",PrimitiveType.Cube,new Vector3(option==0?side*.06f:0,-.85f+row*.42f,option==0?0:-.05f),new Vector3(option==0?.03f:1.43f,.38f,option==0?.78f:.025f),b);}}else{Piece(t,"RTGCore",PrimitiveType.Cylinder,new Vector3(1.3f,0,0),new Vector3(.6f,.6f,.6f),g);for(int i=0;i<5;i++)Piece(t,"RadiatorFin",PrimitiveType.Cube,new Vector3(1.3f,-.45f+i*.22f,0),new Vector3(.9f,.04f,.9f),m);}}
 if(cat==3){for(int i=0;i<=option;i++)Piece(t,"BatteryCell",PrimitiveType.Cube,new Vector3((i-option*.5f)*.28f,0,0),new Vector3(.24f,.6f,.6f),g);}
 if(cat==4){Piece(t,"EngineMount",PrimitiveType.Cube,Vector3.zero,new Vector3(.6f,.12f,.6f),m);Piece(t,"PropellantTank",PrimitiveType.Sphere,new Vector3(0,-.2f,0),Vector3.one*(option==0?.35f:.6f),g);Piece(t,"ThrusterNozzle",PrimitiveType.Cylinder,new Vector3(0,-.55f,0),new Vector3(.3f,.14f,.3f),option==2?glass:m);}
 if(cat==5){Piece(t,"AntennaMount",PrimitiveType.Cube,Vector3.zero,new Vector3(.4f,.1f,.4f),pcb);Piece(t,"AntennaMast",PrimitiveType.Cylinder,new Vector3(0,.23f,0),new Vector3(.05f,.23f,.05f),m);if(option==0)Piece(t,"Patch",PrimitiveType.Cube,new Vector3(0,.45f,0),new Vector3(.6f,.05f,.6f),g);else{Piece(t,"ParabolicDish",PrimitiveType.Sphere,new Vector3(0,.48f,0),new Vector3(.6f+option*.35f,.12f,.6f+option*.35f),m);Piece(t,"Feed",PrimitiveType.Cylinder,new Vector3(0,.65f,0),new Vector3(.06f,.15f,.06f),glass);}}
 if(cat==6){for(int i=0;i<(option==0?1:3);i++)Piece(t,"ReactionWheel",PrimitiveType.Cylinder,new Vector3((i-1)*.25f,0,0),new Vector3(.2f,.12f,.2f),m);if(option==2)Piece(t,"StarTracker",PrimitiveType.Cube,new Vector3(0,.3f,0),Vector3.one*.3f,glass);}
 if(cat==7){for(int i=0;i<(option==2?3:2);i++)Piece(t,option==2?"SunshieldLayer":"ThermalPanel",PrimitiveType.Cube,new Vector3(0,0,i*.09f),new Vector3(option==2?2.6f:1.5f,option==2?3.3f:1.6f,.045f),option==0?g:m);}
 if(cat==8){Piece(t,"ComputerBoard",PrimitiveType.Cube,Vector3.zero,new Vector3(.6f,.06f,.6f),pcb);for(int i=0;i<3;i++)Piece(t,"Processor",PrimitiveType.Cube,new Vector3(-.18f+i*.18f,.08f,0),Vector3.one*.13f,m);if(option>0)Piece(t,"RadiationShield",PrimitiveType.Cube,new Vector3(0,.2f,0),new Vector3(.65f,.08f,.65f),g);}
 if(cat==9){Piece(t,"RocketStage",PrimitiveType.Cylinder,Vector3.zero,new Vector3(.35f+option*.1f,1,.35f+option*.1f),m);Piece(t,"Fairing",PrimitiveType.Sphere,new Vector3(0,1,0),new Vector3(.4f,.6f,.4f),g);}
 if(cat==10){Piece(t,"GroundBase",PrimitiveType.Cube,Vector3.zero,Vector3.one*.4f,m);Piece(t,"GroundDish",PrimitiveType.Sphere,new Vector3(0,.5f,0),new Vector3(.8f+option*.4f,.15f,.8f+option*.4f),m);}
 cv.prefabs[cat*3+option]=PrefabUtility.SaveAsPrefabAsset(root,"Assets/AssetHendrix/Prefabs/Catalog/"+root.name+".prefab");Object.DestroyImmediate(root);
 }
 cv.Sync();EditorUtility.SetDirty(cv);AssetDatabase.SaveAssets();return "33 catalog prefabs created";
 }}
